import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const asset = join(root, 'assets', 'cat', 'deep-sleep-cat-sprite.webp')
const target = join(root, 'src', 'client', 'cat-sprite.generated.ts')
const encoded = readFileSync(asset).toString('base64')

writeFileSync(
  target,
  '// Generated by scripts/embed-cat-sprite.mjs; do not edit.\n'
  + `export const CAT_SPRITE_DATA_URI: string = 'data:image/webp;base64,${encoded}'\n`,
)
console.log(`embedded assets/cat/deep-sleep-cat-sprite.webp (${encoded.length} base64 chars)`)
